 return six.get_method_function(func).__name__
 raise ValueError("Function %s is not a method of: %s" % (func, obj))
```

**After**:


```python
def _find_method(obj, func):
 if obj:
 try:
 func_self = six.get_method_self(func)
 except AttributeError: # func has no __self__
 pass
 else:
 if func_self is obj:
 func_function = six.get_method_function(func)
 # Look for the function in the class dict to handle name mangling
 for name, value in obj.__class__.__dict__.items():
 if value is func_function:
 return name
 # Fallback to original approach if not found in class dict
 return func_function.__name__
 raise ValueError("Function %s is not a method of: %s" % (func, obj))
```



